import itertools

# 4x4 Sudoku with block size 2
n = 4
block_size = 2

# Fixed assignments
fixed = {7: 2, 9: 1, 12: 4}

# Indices to positions
def idx_to_rc(idx):
    return idx // n, idx % n

# Build constraints
# We'll use backtracking

def solve():
    grid = [0] * 16
    for idx, val in fixed.items():
        grid[idx] = val

    # Find empty cells
    empty = [i for i in range(16) if grid[i] == 0]

    # Precompute neighbors for each cell: same row, col, block
    row_cells = [[i*n + j for j in range(n)] for i in range(n)]
    col_cells = [[i*n + j for i in range(n)] for j in range(n)]
    block_cells = {}
    for bi in range(0, n, block_size):
        for bj in range(0, n, block_size):
            cells = []
            for i in range(bi, bi+block_size):
                for j in range(bj, bj+block_size):
                    cells.append(i*n + j)
            for cell in cells:
                block_cells[cell] = cells

    def is_valid(grid, idx, val):
        r, c = idx_to_rc(idx)
        # Check row
        for j in range(n):
            if j != c and grid[r*n + j] == val:
                return False
        # Check column
        for i in range(n):
            if i != r and grid[i*n + c] == val:
                return False
        # Check block
        for cell in block_cells[idx]:
            if cell != idx and grid[cell] == val:
                return False
        return True

    def backtrack(pos):
        if pos == len(empty):
            return True
        idx = empty[pos]
        for val in range(1, 5):
            if is_valid(grid, idx, val):
                grid[idx] = val
                if backtrack(pos + 1):
                    return True
                grid[idx] = 0
        return False

    if backtrack(0):
        return grid
    return None

sol = solve()
if sol:
    print("SAT")
    print(sol)
    # Print grid
    for i in range(4):
        print(sol[i*4:(i+1)*4])
else:
    print("UNSAT")
